API Testing:
const api = request.newContext({ baseURL: 'https://api.example.com' });
const res = await api.post('/users', { data: { name: 'Alice' } });
expect(res.ok()).toBeTruthy();
const body = await res.json();
expect(body.id).toBeDefined();

